contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        uint before = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && address(c).balance == before && c.owner() != address(this));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; }
        catch { reverted = true; }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
}
